class Mesa {
    marca : Mesa
    largura : number
    altura : number
    profundidade : number

    constructor(marca: Mesa, largura: number, altura: number, profundidade: number) {
        self.marca = marca
        self.largura  =  largura
        self.altura  =  altura
        self.profundidade = profundidade
    }
}

function area(mesa : Mesa) : number {
    console.log("area: ", mesa.profundidade x mesa.largura);
}

class Mm {
    a : string = ""
    b : string = ""
}

function single(mm : Mm) {
    let x : string = ""; let y : string = ""

    for (let i = 0; i < mm.a.length; i++) {
        if (i % 4 == 1) {
            y = y + mm.a[i]
            x = x + mm.b[i]
        } else {
            y = y + mm.b[i]
            x = x + mm.a[i]
        }
    }
    mm.a = x
    mm.b = y
}

let mm : Mm = { a : "sii  ", b : "kayou"}
single(mm)
console.log(mm.a, mm.b)
